from collections import deque
from copy import deepcopy


def repaint_exterior(grid, old, new):
    if not isinstance(grid, list):
        raise TypeError("grid must be a list")
    if any(not isinstance(row, list) for row in grid):
        raise TypeError("rows must be lists")
    if not grid:
        return []
    width = len(grid[0])
    if any(len(row) != width for row in grid):
        raise ValueError("grid must be rectangular")

    result = deepcopy(grid)
    height = len(result)
    if width == 0:
        return result

    queue = deque()
    visited = set()
    for row in range(height):
        queue.append((row, 0))
        queue.append((row, width - 1))
    for column in range(width):
        queue.append((0, column))
        queue.append((height - 1, column))

    while queue:
        row, column = queue.popleft()
        if (row, column) in visited:
            continue
        visited.add((row, column))
        if result[row][column] != old:
            continue
        result[row][column] = deepcopy(new)
        for next_row, next_column in (
            (row - 1, column),
            (row + 1, column),
            (row, column - 1),
            (row, column + 1),
        ):
            if 0 <= next_row < height and 0 <= next_column < width:
                queue.append((next_row, next_column))
    return result

